-- Create "connect_listeners" table
CREATE TABLE "connect_listeners" ("id" character varying NOT NULL, "org_id" character varying NOT NULL, "gateway_group_id" character varying NOT NULL, "auth_mode" character varying NOT NULL, "hostname" character varying NOT NULL DEFAULT '', "port_allocation_id" character varying NOT NULL, "certificate_id" character varying NULL, PRIMARY KEY ("id"), CONSTRAINT "connect_listeners_certificates_certificate" FOREIGN KEY ("org_id", "certificate_id") REFERENCES "certificates" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "connect_listeners_port_allocations_port" FOREIGN KEY ("org_id", "port_allocation_id") REFERENCES "port_allocations" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "connect_listeners_orgs" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "connectlistener_certificate_id" to table: "connect_listeners"
CREATE INDEX "connectlistener_certificate_id" ON "connect_listeners" ("certificate_id");
-- Create index "connectlistener_gateway_group_id" to table: "connect_listeners"
CREATE INDEX "connectlistener_gateway_group_id" ON "connect_listeners" ("gateway_group_id");
-- Create index "connectlistener_org_id_id" to table: "connect_listeners"
CREATE UNIQUE INDEX "connectlistener_org_id_id" ON "connect_listeners" ("org_id", "id");
-- Create index "connectlistener_port_allocation_id" to table: "connect_listeners"
CREATE UNIQUE INDEX "connectlistener_port_allocation_id" ON "connect_listeners" ("port_allocation_id");
-- Create "connect_authorities" table
CREATE TABLE "connect_authorities" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" character varying NOT NULL, "authority" character varying NOT NULL, "connect_listener_id" character varying NOT NULL, "route_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "connect_authorities_connect_listeners_listener" FOREIGN KEY ("org_id", "connect_listener_id") REFERENCES "connect_listeners" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "connect_authorities_routes_route" FOREIGN KEY ("org_id", "route_id") REFERENCES "routes" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "connect_authorities_orgs" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "connectauthority_connect_listener_id_authority" to table: "connect_authorities"
CREATE UNIQUE INDEX "connectauthority_connect_listener_id_authority" ON "connect_authorities" ("connect_listener_id", "authority");
-- Create index "connectauthority_org_id_id" to table: "connect_authorities"
CREATE UNIQUE INDEX "connectauthority_org_id_id" ON "connect_authorities" ("org_id", "id");
-- Create index "connectauthority_route_id" to table: "connect_authorities"
CREATE INDEX "connectauthority_route_id" ON "connect_authorities" ("route_id");
-- Modify "route_tcp" table
ALTER TABLE "route_tcp" ALTER COLUMN "port_allocation_id" DROP NOT NULL, ADD COLUMN "connect_listener_id" character varying NULL, ADD CONSTRAINT "route_tcp_connect_listeners_listener" FOREIGN KEY ("org_id", "connect_listener_id") REFERENCES "connect_listeners" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION;
-- Create index "routetcp_connect_listener_id" to table: "route_tcp"
CREATE INDEX "routetcp_connect_listener_id" ON "route_tcp" ("connect_listener_id");
